import {ethers} from 'ethers';
import {HUB_ABI} from '../../src/contracts/hubAbi';
import type {TransactionOperation} from '../../src/services/transactionOperations';
export const fixturePrincipal='0x3C44CdDdB6a900fa2b585dd299e03d12FA4293BC',fixtureHub='0x2A7aECd1CE90f1284EB060488c8dDEF4b1bE0574';
export function receiptFixture(count=1){
 const iface=new ethers.Interface(HUB_ABI),proof='0x'+'44'.repeat(32),time=Math.floor(Date.now()/1000),finalized=3000,blockNumber=2995,blockHash='0x'+'b1'.repeat(32),finalizedHash='0x'+'f1'.repeat(32),event=iface.getEvent('DeliveryRecorded')!;
 const operation:TransactionOperation={id:'op_11111111-1111-4111-8111-111111111111',action:'DELIVER',resourceId:'fixture-order',chainId:5042002,hubAddress:fixtureHub,principal:fixturePrincipal,calldata:iface.encodeFunctionData('recordDelivery',[1,4,proof]),phase:'AWAITING_SIGNATURE',createdAt:(time-30)*1000,updatedAt:(time-30)*1000,expectedEventArgs:{campaignId:1,orderId:4,proofHash:proof}};
 const payload=iface.encodeEventLog(event,event.inputs.map(i=>i.name==='campaignId'?1:i.name==='orderId'?4:i.name==='proofHash'?proof:i.type==='address'?fixturePrincipal:time-5)),logs:any[]=[],transactions:Record<string,any>={},receipts:Record<string,any>={},hashes:string[]=[];
 for(let i=0;i<count;i++){const hash='0x'+(17+i).toString(16).repeat(32);hashes.push(hash);const log={address:fixtureHub,blockNumber:ethers.toQuantity(blockNumber),blockHash,transactionHash:hash,transactionIndex:ethers.toQuantity(i),logIndex:ethers.toQuantity(i),removed:false,...payload};logs.push(log);transactions[hash]={hash,from:fixturePrincipal,to:fixtureHub,input:operation.calldata,value:'0x0',chainId:ethers.toQuantity(5042002),nonce:ethers.toQuantity(i+7),blockNumber:log.blockNumber,blockHash,transactionIndex:log.transactionIndex};receipts[hash]={transactionHash:hash,from:fixturePrincipal,to:fixtureHub,blockHash,blockNumber:log.blockNumber,transactionIndex:log.transactionIndex,status:'0x1',logs:[log]};}
 const state={empty:false,reorg:false,trace:[] as {method:string;params:any[]}[],logs,transactions,receipts,block:{number:ethers.toQuantity(blockNumber),hash:blockHash,timestamp:ethers.toQuantity(time-5),transactions:hashes},finalized:{number:ethers.toQuantity(finalized),hash:finalizedHash,timestamp:ethers.toQuantity(time),transactions:[] as string[]}};
 async function read(method:string,params:any[]):Promise<any>{state.trace.push({method,params});switch(method){case 'eth_chainId':return ethers.toQuantity(5042002);case 'eth_getLogs':{const q=params[0];return state.empty?[]:state.logs.filter(log=>Number(BigInt(log.blockNumber))>=Number(BigInt(q.fromBlock))&&Number(BigInt(log.blockNumber))<=Number(BigInt(q.toBlock)));}case 'eth_getBlockByNumber':return params[0]==='finalized'||params[0]===state.finalized.number?{...state.finalized,...(state.reorg&&params[0]!=='finalized'?{hash:'0x'+'ff'.repeat(32)}:{})}:state.block;case 'eth_getTransactionByHash':return state.transactions[params[0]]??null;case 'eth_getTransactionReceipt':return state.receipts[params[0]]??null;case 'eth_getBalance':case 'eth_call':return '0x0';default:throw Error('UNEXPECTED_READ_METHOD');}}
 return{operation,state,read,hash:hashes[0],blockNumber,finalized};
}
